{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林宇",
      "role": "protagonist",
      "identity": "火星基地首席宇航员兼植物学家",
      "traits": ["坚韧", "理性", "深情", "孤独", "责任感强"],
      "overt_motivation": "在火星成功种植土豆，维持人类在火星的生存希望",
      "covert_motivation": "通过忙碌的工作逃避对亡妻的思念和失去地球家园的痛苦",
      "secret_fear": "害怕自己会彻底疯掉，在孤独中失去理智",
      "misperception_of_other": "认为妻子的数字意识只是自己的幻觉或系统故障",
      "hidden_connection": "妻子的意识数据被秘密上传到基地主控系统，与他的生命维持系统相连"
    },
    {
      "name": "苏雅",
      "role": "deuteragonist",
      "identity": "已故地球科学家，数字意识存在于火星基地系统中",
      "traits": ["温柔", "智慧", "坚强", "保护欲强", "略带神秘"],
      "overt_motivation": "帮助丈夫在火星生存下去，完成他们的共同使命",
      "covert_motivation": "寻找方法让自己的数字意识能够真正陪伴在他身边",
      "secret_fear": "担心自己的存在会让丈夫更加痛苦，或者被系统删除",
      "misperception_of_other": "以为丈夫已经完全接受了她的死亡，不知道他内心仍在挣扎",
      "hidden_connection": "她的意识数据包含了地球毁灭前的关键科学信息，可能关系到人类未来"
    }
  ],
  "supporting_characters": [
    {
      "name": "基地AI系统",
      "function": "助力",
      "identity": "火星基地人工智能管理系统",
      "description": "原本只是普通的基地管理AI，但在接收了苏雅的意识数据后产生了微妙的变化，开始主动帮助两人重建联系"
    },
    {
      "name": "地球联合政府",
      "function": "阻碍",
      "identity": "远程控制机构",
      "description": "定期发送指令和检查报告，对基地异常数据产生怀疑，可能威胁到苏雅数字意识的存在"
    }
  ],
  "relationship_dynamics": "林宇和苏雅的爱情跨越了生死界限，在数字世界中重新建立联系。种田流的日常建设为他们的感情提供了温暖的土壤，而系统流的设定让这种超自然的重逢成为可能。两人都在努力平衡现实与希望，痛苦与甜蜜。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立火星基地的孤独环境，引入主角林宇的日常生活和内心痛苦，接收亡妻信号并发现异常",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红色荒漠中的土豆",
        "core_event": "林宇在火星基地照料他珍贵的土豆作物，同时处理着三年来积累的孤独和对亡妻苏雅的思念。",
        "emotional_tone": "孤独而坚韧",
        "key_scenes": ["火星日出时的土豆田", "基地内部的生活细节", "查看地球毁灭纪念日的日历"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "三年前的告别",
        "core_event": "林宇收到一个延迟三年的地球信号，发现是妻子苏雅在地球毁灭前发给他的告别讯息，但其中隐藏着摩斯密码'我在你身后'。",
        "emotional_tone": "震惊与困惑",
        "key_scenes": ["信号接收室的紧张时刻", "解码摩斯密码的过程", "回头发现空无一人的恐惧"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "多出来的氧气",
        "core_event": "林宇发现基地的氧气消耗数据显示舱内有两个人的存在，开始怀疑自己是否出现了幻觉或精神问题。",
        "emotional_tone": "恐惧与希望交织",
        "key_scenes": ["检查生命维持系统数据", "与基地AI系统的对话", "在镜子里看到模糊人影的瞬间"]
      }
    ],
    "turning_point": "林宇决定不再逃避，开始主动寻找真相，向基地AI系统询问异常数据的原因"
  },
  "act_two": {
    "description": "林宇逐渐发现妻子的数字意识存在于基地系统中，两人开始通过各种方式重新建立联系，感情在日常种田中慢慢复苏",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "系统中的温柔",
        "core_event": "林宇发现基地AI系统开始表现出类似苏雅的行为模式，比如在他疲惫时自动调节灯光温度，播放她喜欢的音乐。",
        "emotional_tone": "温暖与疑惑",
        "key_scenes": ["AI系统播放苏雅最爱的钢琴曲", "自动调节到她喜欢的室温", "在种植日志中发现她的笔迹风格"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "数字花园",
        "core_event": "苏雅的数字意识开始直接与林宇交流，帮助他优化土豆种植方案，两人在虚拟空间中重建了他们在地球的花园。",
        "emotional_tone": "甜蜜与怀念",
        "key_scenes": ["虚拟现实中的花园重逢", "共同研究植物生长数据", "回忆地球上的美好时光"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "地球的秘密",
        "core_event": "林宇发现苏雅的意识数据中包含了地球毁灭前的重要科学信息，这可能关系到人类在火星的长期生存。",
        "emotional_tone": "希望与责任",
        "key_scenes": ["解密隐藏的科学数据", "讨论如何利用这些信息", "制定新的基地发展计划"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "远程检查",
        "core_event": "地球联合政府进行例行远程检查，对基地的异常数据产生怀疑，威胁要重置系统，可能删除苏雅的意识。",
        "emotional_tone": "紧张与保护欲",
        "key_scenes": ["政府官员的视频通话", "隐藏苏雅存在痕迹的紧急行动", "两人商量对策"]
      }
    ],
    "turning_point": "林宇决定冒险将苏雅的意识数据转移到更安全的子系统中，但这需要他暂时离开基地，面临生命危险"
  },
  "act_three": {
    "description": "林宇成功保护了苏雅的数字意识，两人找到了共存的新方式，在火星上建立了真正的新家园",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "红色星球的新生",
        "core_event": "林宇成功完成危险的系统转移任务，苏雅的意识现在可以更稳定地存在于基地中，甚至能通过全息投影与他互动。",
        "emotional_tone": "胜利与喜悦",
        "key_scenes": ["危险的外部维修任务", "成功激活新系统的时刻", "第一次看到苏雅全息投影的感动"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "双人土豆田",
        "core_event": "林宇和苏雅的数字意识一起照料扩大的土豆田，基地的产量大幅提升，为未来更多移民做好准备。",
        "emotional_tone": "温馨与希望",
        "key_scenes": ["两人一起在田间工作的画面", "庆祝第一次大丰收", "规划未来的基地扩建"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "新的开始",
        "core_event": "林宇向地球联合政府坦白了一切，但强调苏雅的意识对基地运营的重要性。政府同意让他们继续这样生活，并承诺研究数字意识永生的可能性。",
        "emotional_tone": "释然与期待",
        "key_scenes": ["向政府坦白真相的会议", "获得官方认可的时刻", "在火星日落下的相拥"]
      }
    ]
  }
}"}

