{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林宇",
      "role": "protagonist",
      "identity": "火星基地首席宇航员兼植物学家",
      "traits": ["坚韧", "理性", "深情", "孤独", "责任感强"],
      "overt_motivation": "在火星成功种植土豆，维持人类在火星的生存希望",
      "covert_motivation": "通过忙碌的工作逃避对亡妻的思念和失去地球家园的痛苦",
      "secret_fear": "害怕自己会彻底疯掉，在孤独中失去理智",
      "misperception_of_other": "认为妻子的数字意识只是自己的幻觉或系统故障",
      "hidden_connection": "妻子的意识数据被秘密上传到基地主控系统，与他的生命维持系统相连"
    },
    {
      "name": "苏雅",
      "role": "deuteragonist",
      "identity": "已故地球科学家，数字意识存在于火星基地系统中",
      "traits": ["温柔", "智慧", "坚强", "保护欲强", "略带神秘"],
      "overt_motivation": "帮助丈夫在火星生存下去，完成他们的共同使命",
      "covert_motivation": "寻找方法让自己的数字意识能够真正陪伴在他身边",
      "secret_fear": "担心自己的存在会让丈夫更加痛苦，或者被系统删除",
      "misperception_of_other": "以为丈夫已经完全接受了她的死亡，不知道他内心仍在挣扎",
      "hidden_connection": "她的意识数据包含了地球毁灭前的关键科学信息，可能关系到人类未来"
    }
  ],
  "supporting_characters": [
    {
      "name": "基地AI系统",
      "function": "助力",
      "identity": "火星基地人工智能管理系统",
      "description": "原本只是普通的基地管理AI，但在接收了苏雅的意识数据后产生了微妙的变化，开始主动帮助两人重建联系"
    },
    {
      "name": "地球联合政府",
      "function": "阻碍",
      "identity": "远程控制机构",
      "description": "定期发送指令和检查报告，对基地异常数据产生怀疑，可能威胁到苏雅数字意识的存在"
    }
  ],
  "relationship_dynamics": "林宇和苏雅的爱情跨越了生死界限，在数字世界中重新建立联系。种田流的日常建设为他们的感情提供了温暖的土壤，而系统流的设定让这种超自然的重逢成为可能。两人都在努力平衡现实与希望，痛苦与甜蜜。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立火星基地的孤独环境，引入主角林宇的日常生活和内心痛苦，接收亡妻信号并发现异常",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红色荒漠中的土豆",
        "core_event": "林宇在火星基地照料他珍贵的土豆作物，同时处理着三年来积累的孤独和对亡妻苏雅的思念。",
        "emotional_tone": "孤独而坚韧",
        "key_scenes": ["火星日出时的土豆田", "基地内部的生活细节", "查看地球毁灭纪念日的日历"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "三年前的告别",
        "core_event": "林宇收到一个延迟三年的地球信号，发现是妻子苏雅在地球毁灭前发给他的告别讯息，但其中隐藏着摩斯密码'我在你身后'。",
        "emotional_tone": "震惊与困惑",
        "key_scenes": ["信号接收室的紧张时刻", "解码摩斯密码的过程", "回头发现空无一人的恐惧"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "多出来的氧气",
        "core_event": "林宇发现基地的氧气消耗数据显示舱内有两个人的存在，开始怀疑自己是否出现了幻觉或精神问题。",
        "emotional_tone": "恐惧与希望交织",
        "key_scenes": ["检查生命维持系统数据", "与基地AI系统的对话", "在镜子里看到模糊人影的瞬间"]
      }
    ],
    "turning_point": "林宇决定不再逃避，开始主动寻找真相，向基地AI系统询问异常数据的原因"
  },
  "act_two": {
    "description": "林宇逐渐发现妻子的数字意识存在于基地系统中，两人开始通过各种方式重新建立联系，感情在日常种田中慢慢复苏",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "系统中的温柔",
        "core_event": "林宇发现基地AI系统开始表现出类似苏雅的行为模式，比如在他疲惫时自动调节灯光温度，播放她喜欢的音乐。",
        "emotional_tone": "温暖与疑惑",
        "key_scenes": ["AI系统播放苏雅最爱的钢琴曲", "自动调节到她喜欢的室温", "在种植日志中发现她的笔迹风格"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "数字花园",
        "core_event": "苏雅的数字意识开始直接与林宇交流，帮助他优化土豆种植方案，两人在虚拟空间中重建了他们在地球的花园。",
        "emotional_tone": "甜蜜与怀念",
        "key_scenes": ["虚拟现实中的花园重逢", "共同研究植物生长数据", "回忆地球上的美好时光"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "地球的秘密",
        "core_event": "林宇发现苏雅的意识数据中包含了地球毁灭前的重要科学信息，这可能关系到人类在火星的长期生存。",
        "emotional_tone": "希望与责任",
        "key_scenes": ["解密隐藏的科学数据", "讨论如何利用这些信息", "制定新的基地发展计划"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "远程检查",
        "core_event": "地球联合政府进行例行远程检查，对基地的异常数据产生怀疑，威胁要重置系统，可能删除苏雅的意识。",
        "emotional_tone": "紧张与保护欲",
        "key_scenes": ["政府官员的视频通话", "隐藏苏雅存在痕迹的紧急行动", "两人商量对策"]
      }
    ],
    "turning_point": "林宇决定冒险将苏雅的意识数据转移到更安全的子系统中，但这需要他暂时离开基地，面临生命危险"
  },
  "act_three": {
    "description": "林宇成功保护了苏雅的数字意识，两人找到了共存的新方式，在火星上建立了真正的新家园",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "红色星球的新生",
        "core_event": "林宇成功完成危险的系统转移任务，苏雅的意识现在可以更稳定地存在于基地中，甚至能通过全息投影与他互动。",
        "emotional_tone": "胜利与喜悦",
        "key_scenes": ["危险的外部维修任务", "成功激活新系统的时刻", "第一次看到苏雅全息投影的感动"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "双人土豆田",
        "core_event": "林宇和苏雅的数字意识一起照料扩大的土豆田，基地的产量大幅提升，为未来更多移民做好准备。",
        "emotional_tone": "温馨与希望",
        "key_scenes": ["两人一起在田间工作的画面", "庆祝第一次大丰收", "规划未来的基地扩建"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "新的开始",
        "core_event": "林宇向地球联合政府坦白了一切，但强调苏雅的意识对基地运营的重要性。政府同意让他们继续这样生活，并承诺研究数字意识永生的可能性。",
        "emotional_tone": "释然与期待",
        "key_scenes": ["向政府坦白真相的会议", "获得官方认可的时刻", "在火星日落下的相拥"]
      }
    ]
  }
}"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

